export type Filter = "all" | "brand" | "campaign";

export type ProjectMedia = {
  type: "image" | "video";
  src: string;
  alt: string;
  poster?: string;
  caption?: string;
  playback?: "loop" | "controls";
  previewFit?: "cover" | "contain";
};

export type ProjectSection = {
  title: string;
  paragraphs: string[];
  media?: ProjectMedia[];
  layout?: "single" | "duo" | "triptych" | "portrait";
  eyebrow?: string;
  campaign?: {
    number: string;
    title: string;
    year: string;
    descriptor: string;
  };
};

export type Project = {
  id: string;
  title: string;
  number: string;
  year: string;
  tags: string[];
  filter: Exclude<Filter, "all">;
  role: string;
  tone: string;
  lede: string;
  paragraphs: string[];
  works?: string[];
  media?: ProjectMedia[];
  sections?: ProjectSection[];
};

const image = (src: string, alt: string, caption?: string): ProjectMedia => ({ type: "image", src, alt, caption });
const video = (src: string, alt: string, poster?: string, playback: "loop" | "controls" = "controls", caption?: string): ProjectMedia => ({ type: "video", src, alt, poster, playback, caption });
const artwork = (src: string, alt: string, caption?: string): ProjectMedia => ({ type: "image", src, alt, caption, previewFit: "contain" });
const framedVideo = (src: string, alt: string, poster?: string, playback: "loop" | "controls" = "controls", caption?: string): ProjectMedia => ({ type: "video", src, alt, poster, playback, caption, previewFit: "contain" });

